class Solution {
public:
    int numberOfNodes(int n, std::vector<int>& queries) {
        std::vector<int> flips(n + 1, 0);
        for (int q : queries) flips[q] ^= 1;
        int ans = 0;
        for (int i = 1; i <= n; i++) {
            int p = i / 2;
            if (p > 0) flips[i] ^= flips[p];
            if (flips[i] == 1) ans++;
        }
        return ans;
    }
};

