var numberOfNodes = function(n, queries) {
    const flips = new Array(n + 1).fill(0);
    for (const q of queries) flips[q] ^= 1;
    let ans = 0;
    for (let i = 1; i <= n; i++) {
        const p = Math.floor(i / 2);
        if (p > 0) flips[i] ^= flips[p];
        if (flips[i] === 1) ans++;
    }
    return ans;
};
